buckets = [
    {"name": "app-logs", "public_block": True, "encryption": "aws:kms"},
    {"name": "mkt-img", "public_block": False, "encryption": None},
    {"name": "backup", "public_block": True, "encryption": None},
]
for b in buckets:
    issues = []
    if not b["public_block"]: issues.append("퍼블릭 차단 꺼짐")
    if not b["encryption"]: issues.append("기본 암호화 없음")
    print(b["name"], "→", ", ".join(issues) or "양호")
# app-logs → 양호
# mkt-img → 퍼블릭 차단 꺼짐, 기본 암호화 없음
# backup → 기본 암호화 없음
